#!/bin/bash
# LiteX CVA6 SoC on the VC707: generated by LiteX, synthesised by SVS,
# placed and routed by Vivado.
#
#   test/cva6_litex/run.sh [gen|vlt|svs|vivado|all]...      (default: all)
#
#   gen     examples/vc707-litex/vc707_litex.py --cpu-type cva6 (via gen_soc.py):
#           Verilog + LiteX's Vivado tcl/xdc + the compiled BIOS ROM image
#   vlt     verilator --json-only over the SoC (sources, include dirs and order
#           taken from LiteX's own tcl; Vivado's unisim_comp.v for the
#           primitive declarations, which the import drops again)
#   svs     SVS: verilator front end -> BIR pipeline -> gate_map per module
#           (top with I/O buffers) -> spliced -> hierarchical EDIF
#   vivado  read_edif + LiteX's xdc -> link/opt/place/route -> reports + .bit
#
# Knobs (environment):
#   OUT            output root                (~/svs-gatesim/cva6-litex)
#   SOC_ARGS       vc707_litex.py SoC options (the 1 GB DDR3 + ethmin variant:
#                  --with-ddr --with-ddr64 --with-ethmin-phy --with-led-chaser)
#   CVA6_VARIANT   LiteX CPU variant          (standard)
#   XC7            xc7-bitstream-tools checkout (~/xc7-bitstream-tools; its
#                  .venv, litex-deps/ and examples/vc707-litex are used)
#   SV_SUITE       sv_suite binary            (this tree's _build)
#   SVS_MAX_MEM_MB memory cap for sv_suite    (24000)
#   VIVADO         vivado binary              (/opt/Xilinx/Vivado/2020.1/bin/vivado)
#   VIVADO_JOBS    route/place threads        (8)
set -u
HERE=$(cd "$(dirname "$0")" && pwd); ROOT=$(cd "$HERE/../.." && pwd)
OUT=${OUT:-$HOME/svs-gatesim/cva6-litex}
XC7=${XC7:-$HOME/xc7-bitstream-tools}
SOC_ARGS=${SOC_ARGS:---with-ddr --with-ddr64 --with-ethmin-phy --with-led-chaser}
CVA6_VARIANT=${CVA6_VARIANT:-standard}
SV=${SV_SUITE:-$ROOT/_build/default/sv_suite.exe}
VIVADO=${VIVADO:-/opt/Xilinx/Vivado/2020.1/bin/vivado}
UNISIM_COMP=${UNISIM_COMP:-$(dirname "$(dirname "$VIVADO")")/data/verilog/src/unisim_comp.v}
TOP=xilinx_vc707
PART=xc7vx485tffg1761-2
GW=$OUT/soc/gateware
mkdir -p "$OUT"
export SVS_MAX_MEM_MB=${SVS_MAX_MEM_MB:-24000}

stage_gen() {
  echo "== gen: LiteX SoC -> $OUT/soc"
  rm -rf "$OUT/soc"
  (cd "$XC7" && PATH="$XC7/.venv/bin:$(dirname "$VIVADO"):$PATH" \
     PYTHONPATH="$XC7/litex-deps/pythondata-cpu-cva6" \
     "$XC7/.venv/bin/python" "$HERE/gen_soc.py" \
       --cpu-type cva6 --cpu-variant "$CVA6_VARIANT" $SOC_ARGS --flow svs \
       --build --no-compile-gateware --output-dir "$OUT/soc") > "$OUT/gen.log" 2>&1 \
    || { echo "gen failed: $OUT/gen.log"; tail -20 "$OUT/gen.log"; exit 2; }
  ls -la "$GW/$TOP.v" "$GW/${TOP}_rom.init"
}

stage_vlt() {
  echo "== vlt: verilator --json-only -> $OUT/vlt/soc.json"
  local tcl=$GW/$TOP.tcl
  [ -f "$tcl" ] || { echo "no $tcl: run the gen stage"; exit 2; }
  # LiteX's tcl is the source of truth for the file list, its order and the
  # include path -- the same inputs Vivado's own synth_design would get
  sed -n 's/^read_verilog \(-v \)\?{\(.*\)}$/\2/p' "$tcl" > "$OUT/files.txt"
  sed -n 's/.*-include_dirs {\([^}]*\)}.*/\1/p' "$tcl" | tr ' ' '\n' | sed '/^$/d' > "$OUT/incdirs.txt"
  mkdir -p "$OUT/vlt"
  verilator --no-timing --json-only --json-only-output "$OUT/vlt/soc.json" \
    -Wno-fatal -Wno-lint -Wno-style -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND -Wno-UNOPTFLAT \
    -Wno-CASEINCOMPLETE -Wno-MULTIDRIVEN -Wno-PINMISSING -Wno-IMPLICIT -Wno-MULTITOP \
    +define+SYNTHESIS=1 --timescale 1ns/1ps --unroll-count 256 \
    $(sed 's/^/+incdir+/' "$OUT/incdirs.txt") --top-module $TOP \
    "$UNISIM_COMP" $(cat "$OUT/files.txt") --Mdir "$OUT/vlt/obj" > "$OUT/vlt/verilate.log" 2>&1 \
    || { echo "verilator failed: $OUT/vlt/verilate.log"; grep %Error "$OUT/vlt/verilate.log" | head; exit 2; }
  echo "$(wc -l < "$OUT/files.txt") sources; $(du -h "$OUT/vlt/soc.json" | cut -f1) JSON"
}

stage_svs() {
  echo "== svs: synthesis -> $OUT/svs/$TOP.edif"
  [ -s "$OUT/vlt/soc.json" ] || { echo "no $OUT/vlt/soc.json: run the vlt stage"; exit 2; }
  mkdir -p "$OUT/svs/tmp"
  local L=$OUT/svs/synth.lua
  # lua-ml is Lua 2.5: strfind/strsub and while loops, no ipairs/io/os
  cat > "$L" <<EOF
prog = svd.parse("verilator", "$TOP", {"$OUT/vlt/soc.json"})
prog = svd.unroll(prog);         print("pass unroll")
prog = svd.inline(prog);         print("pass inline")
prog = svd.iflift(prog);         print("pass iflift")
prog = svd.blocking_subst(prog); print("pass blocking_subst")
prog = svd.meminfer(prog);       print("pass meminfer")
prog = svd.memlower(prog);       print("pass memlower")
prog = svd.srl_infer(prog);      print("pass srl_infer")
prog = svd.dsp_infer(prog);      print("pass dsp_infer")
print("opts: " .. svd.fpga_opts())
-- every module under the top that SVS holds a body for (svd.children also
-- names the unresolved primitives: MMCME2_ADV, OSERDESE2, GTXE2_CHANNEL...)
kids = svd.children(prog, "$TOP") .. "\n"
svd.write_text("$OUT/svs/children.txt", kids)
have = "," .. svd.module_names(prog) .. ","
n = 0
while kids ~= "" do
  p = strfind(kids, "\n")
  m = strsub(kids, 1, p - 1)
  kids = strsub(kids, p + 1)
  if m ~= "" and strfind(have, "," .. m .. ",", 1, 1) then
    -- children without I/O buffers; only the top's ports are pads
    mapped = svd.gate_map(svd.pick(prog, m), 6, 0)
    prog = svd.splice(prog, m, svd.mapped_to_prog(mapped))
    n = n + 1
    print("mapped " .. n .. " " .. m)
  end
end
mapped = svd.gate_map(svd.pick(prog, "$TOP"), 6, 1)
prog = svd.splice(prog, "$TOP", svd.mapped_to_prog(mapped))
print("mapped top $TOP")
print("wrote " .. svd.write_hier_edif(prog, "$TOP", "$OUT/svs/$TOP.edif"))
EOF
  (cd "$ROOT" && MEM_INIT_DIR="$GW" TMPDIR="$OUT/svs/tmp" \
     /usr/bin/time -f '%e s, %M KB peak' "$SV" script "$L") > "$OUT/svs/synth.log" 2>&1
  local rc=$?
  tail -3 "$OUT/svs/synth.log"
  [ $rc -eq 0 ] && [ -s "$OUT/svs/$TOP.edif" ] || { echo "svs failed (rc $rc): $OUT/svs/synth.log"; exit 2; }
}

stage_vivado() {
  echo "== vivado: place and route -> $OUT/vivado"
  [ -s "$OUT/svs/$TOP.edif" ] || { echo "no EDIF: run the svs stage"; exit 2; }
  mkdir -p "$OUT/vivado"
  sed -e "s#@EDIF@#$OUT/svs/$TOP.edif#" -e "s#@XDC@#$GW/$TOP.xdc#" \
      -e "s#@TOP@#$TOP#g" -e "s#@PART@#$PART#" -e "s#@JOBS@#${VIVADO_JOBS:-8}#" \
      "$HERE/pnr.tcl" > "$OUT/vivado/pnr.tcl"
  (cd "$OUT/vivado" && "$VIVADO" -mode batch -nojournal -source pnr.tcl -log vivado.log) > /dev/null 2>&1
  local rc=$?
  grep -E '^(PNR|ERROR)' "$OUT/vivado/vivado.log" | head -40
  [ $rc -eq 0 ] || { echo "vivado failed (rc $rc): $OUT/vivado/vivado.log"; exit 2; }
}

stages=("$@"); [ ${#stages[@]} -eq 0 ] && stages=(all)
for s in "${stages[@]}"; do
  case $s in
    gen) stage_gen ;; vlt) stage_vlt ;; svs) stage_svs ;; vivado) stage_vivado ;;
    all) stage_gen; stage_vlt; stage_svs; stage_vivado ;;
    *) echo "unknown stage $s (gen|vlt|svs|vivado|all)"; exit 2 ;;
  esac
done
